#!/usr/bin/env node
// scripts/gen-gui-contract.mjs
//
// Dumb generator for the CLI↔GUI boundary contract. The CLI's
// `src/contract.ts` is the single source of truth; this copies its type body
// into a standalone file the GUI consumes, with an AUTO-GENERATED header and a
// content hash for drift detection. No TS parsing — pure string + hash.
//
// Usage:
//   node scripts/gen-gui-contract.mjs [outPath]   # write (default GUI path)
//   node scripts/gen-gui-contract.mjs --check [outPath]  # exit 1 on drift
//
// The default outPath assumes the GUI repo sits beside this one under the
// shared workspace root (../claude-switch-gui). Override with an explicit arg.

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '..');
const SOURCE = path.join(repoRoot, 'src', 'contract.ts');
const DEFAULT_OUT = path.resolve(repoRoot, '..', 'claude-switch-gui', 'src', 'lib', 'contract.generated.ts');

const args = process.argv.slice(2);
const check = args.includes('--check');
const outArg = args.find((a) => !a.startsWith('--'));
const outPath = outArg ? path.resolve(outArg) : DEFAULT_OUT;

/** The type body = everything from the first top-level `export` onward.
 *  Strips the source file's leading comment so the generated file owns its
 *  own header. Hashing this body (not the whole file) keeps drift detection
 *  stable against header/comment edits in the source. */
function typeBody(src) {
  const idx = src.indexOf('\nexport ');
  if (idx === -1) throw new Error('contract.ts has no top-level export');
  return src.slice(idx + 1).trimEnd() + '\n';
}

function render(body, hash) {
  return [
    '// AUTO-GENERATED by claude-switch `npm run gen:gui-contract`. DO NOT EDIT.',
    '// Source of truth: claude-switch/src/contract.ts',
    `// @generated sha256:${hash}`,
    '',
    body,
  ].join('\n');
}

const src = fs.readFileSync(SOURCE, 'utf-8');
const body = typeBody(src);
const hash = crypto.createHash('sha256').update(body).digest('hex');
const expected = render(body, hash);

if (check) {
  if (!fs.existsSync(outPath)) {
    console.error(`drift: generated file missing at ${outPath}`);
    process.exit(1);
  }
  // Compare the full rendered output, not just the header hash — this catches
  // both a stale source (header hash moved) AND hand-edits to the generated
  // body (the "DO NOT EDIT" violation).
  const existing = fs.readFileSync(outPath, 'utf-8');
  if (existing !== expected) {
    console.error(`drift: ${outPath} is out of date or hand-edited — run \`npm run gen:gui-contract\``);
    process.exit(1);
  }
  console.log('contract in sync');
  process.exit(0);
}

fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, expected);
console.log(`wrote ${outPath}`);
